function renderAnswers(q){const area=$('#answersArea');area.innerHTML='';const choice=['mc','mr','tf'].includes(q.type);$('#addAnswer').hidden=!choice||q.type==='tf';$('#shortAnswerWrap').hidden=q.type!=='sa';$('#fillBlankWrap').hidden=q.type!=='fitb';if(!choice)return;if(q.type==='tf'&&q.answers.length!==2)q.answers=[{text:'True',html:'',correct:false},{text:'False',html:'',correct:false}];q.answers.forEach((a,i)=>{const row=document.createElement('div');row.className='qb-answer '+(q.type==='mr'?'multiple ':'')+(a.correct?'is-correct':'');row.innerHTML=`<button type="button" class="qb-answer-marker" title="Mark correct" aria-label="Mark answer ${i+1} correct"></button><input class="ft-input qb-answer-input" value="${esc(a.text)}" data-i="${i}" ${q.type==='tf'?'readonly':''}><button type="button" class="qb-trash" title="Delete answer" ${q.type==='tf'?'hidden':''}>×</button>`;row.querySelector('.qb-answer-marker').onclick=()=>{if(q.type==='mr')a.correct=!a.correct;else q.answers.forEach((x,j)=>x.correct=j===i);q.confidence='high';q.confidenceReason='Correct answer confirmed in Review';saveAutosave();renderAnswers(q);renderQuestionState(q)};row.querySelector('input').oninput=e=>{a.text=e.target.value;a.html='';saveAutosave();renderQuestionState(q)};row.querySelector('.qb-trash').onclick=()=>{q.answers.splice(i,1);renderAnswers(q);saveAutosave()};area.appendChild(row)})}
