$('#startNew').onclick=async()=>{if(state.questions.length&&!await FTDialog.confirm(`This clears ${state.questions.length} current question${state.questions.length===1?'':'s'}. Save a project copy first if you may need them.`,{title:'Start a new project?',confirmLabel:'Clear and start new',danger:true}))return;state.questions=[];state.selected=0;state.sourceName='Untitled question set';state.brightspaceImageFolder='';localStorage.removeItem('questionbridge-autosave');renderReview();show('upload');pop('New project started')};
$('#parsePaste').onclick=async()=>{const txt=$('#pasteText').value;if(!txt.trim())return pop('Paste question text first');state.importSettings.correctMarking=$('#correctMarking').value;const qs=parseTextQuestions(txt,'Pasted questions');await replaceWithParsed(qs,'Pasted questions')};
async function handleFile(file){$('#fileName').textContent='Selected: '+file.name;$('#parseStatus').innerHTML='<span class="ft-muted">Parsing…</span>';try{state.importSettings.correctMarking=$('#correctMarking').value;const lower=file.name.toLowerCase();let result;if(lower.endsWith('.txt'))result={questions:parseTextQuestions(await file.text(),file.name),sourceLabel:'Text question bank'};else if(lower.endsWith('.docx'))result={questions:await parseDocx(file),sourceLabel:'Word / ExamSoft document'};else if(lower.endsWith('.csv'))result=parsePlatformCsv(await file.text(),file.name);else if(lower.endsWith('.xlsx'))result=await parseKahootXlsx(file);else if(lower.endsWith('.rtf'))result=parseExamsoftRtf(await file.text(),file.name);else throw new Error('QuestionBridge reads .docx, .txt, Brightspace/Poll Everywhere .csv, Kahoot .xlsx, and legacy ExamSoft .rtf files.');const qs=result.questions||result;await replaceWithParsed(qs,file.name);$('#parseStatus').innerHTML=`<span class="ft-status-ready">✓ Parsed ${qs.length} question${qs.length===1?'':'s'}</span><br><span class="ft-muted">Source detected: ${esc(result.sourceLabel||'Question bank')}</span>`}catch(err){console.error(err);$('#parseStatus').innerHTML='<span class="ft-status-error">× QuestionBridge could not read this file.</span><br><span class="ft-muted">'+esc(friendlyParseError(err))+'</span>'}}
function friendlyParseError(err){const m=String(err?.message||'');if(m.includes('automatic numbering'))return m;if(m.includes('reads .docx'))return m;return 'Try saving the source as .docx or .txt and uploading again. If the problem continues, review the document for unusual numbering or layout.'}
async function replaceWithParsed(qs,source){if(!qs.length)throw new Error('No questions were detected in this file.');const applyImport=(mode)=>{if(mode==='replace'){state.questions=qs.map(normalizeQuestion);state.selected=0}else{const before=state.questions.length;state.questions.push(...qs.map(normalizeQuestion));state.selected=before}state.sourceName=source||state.sourceName;saveAutosave();renderReview();show('review');pop(`${mode==='append'?'Added':'Parsed'} ${qs.length} question${qs.length===1?'':'s'}`)};if(!state.questions.length){applyImport('replace');return}return await new Promise(resolve=>{openModal('Add or replace questions',`<p>You already have <b>${state.questions.length}</b> question${state.questions.length===1?'':'s'}. What should QuestionBridge do with the <b>${qs.length}</b> imported question${qs.length===1?'':'s'}?</p><div class="ft-btn-row ft-mt-4"><button type="button" class="ft-btn ft-btn-primary" id="importAddBtn">Add to current set</button><button type="button" class="ft-btn" id="importReplaceBtn">Replace everything</button><button type="button" class="ft-btn" id="importCancelBtn">Cancel</button></div>`,null);modalDismiss=()=>{pop('Import cancelled');resolve()};$('#importAddBtn').onclick=()=>{modalDismiss=null;modalCtl.close();applyImport('append');resolve()};$('#importReplaceBtn').onclick=()=>{modalDismiss=null;modalCtl.close();applyImport('replace');resolve()};$('#importCancelBtn').onclick=()=>modalCtl.close()})}
function extractAnswerKey(lines){const marker=lines.findIndex(l=>/^\s*(answer\s*key|answers)\s*:/i.test(typeof l==='string'?l:l.text));if(marker<0)return {lines,entries:[]};const asText=x=>typeof x==='string'?x:x.text;const isTop=marker<Math.max(4,Math.floor(lines.length*.25));let keyEnd=marker+1;if(isTop){while(keyEnd<lines.length&&/^\s*(?:\d+\s*[-.:)]?\s*[A-Z](?:\s*[,;]\s*)?)+\s*$/i.test(asText(lines[keyEnd])))keyEnd++}else keyEnd=lines.length;const segment=lines.slice(marker,keyEnd).map(asText).join(' ');const entries=[];for(const m of segment.matchAll(/(\d+)\s*[-.:)]?\s*([A-Z](?:\s*[,/&+]\s*[A-Z])*)/gi))entries.push({num:Number(m[1]),answer:m[2].toUpperCase().replace(/\s+/g,'')});const kept=isTop?[...lines.slice(0,marker),...lines.slice(keyEnd)]:lines.slice(0,marker);return {lines:kept,entries}}
function parseTextQuestions(text,source='Text'){const clean=text.replace(/\r/g,'');let lines=clean.split('\n');const k=extractAnswerKey(lines);lines=k.lines;const starts=[];const explicit=[];lines.forEach((l,i)=>{const m=l.match(/^\s*Question\s*#?\s*:\s*(\d+)\s*(.*)$/i);if(m)explicit.push({i,num:Number(m[1]),first:m[2]||'',kind:'explicit'})});if(explicit.length){starts.push(...explicit)}else{lines.forEach((l,i)=>{const m=l.match(/^\s*(?:Type:\s*(MA|E|F)\s*)?(?:Q\s*)?(\d+)\s*[.)]\s*(.*)$/i);if(m)starts.push({i,num:Number(m[2]),prefix:m[1],first:m[3],kind:'typed'})})}if(!starts.length&&clean.trim())starts.push({i:0,num:1,first:lines[0]||'',kind:'fallback'});const nums=starts.map(s=>s.num),dups=new Set(nums.filter((n,i)=>nums.indexOf(n)!==i));const keyMap=new Map();k.entries.forEach(e=>{if(!keyMap.has(e.num))keyMap.set(e.num,e.answer)});const positional=dups.size>0&&k.entries.length>=starts.length;const out=[];for(let s=0;s<starts.length;s++){const st=starts[s],end=s+1<starts.length?starts[s+1].i:lines.length,block=lines.slice(st.i,end);block[0]=st.first;while(block.length>1&&isSectionHeading(block[block.length-1]))block.pop();const keyAnswer=positional?k.entries[s]?.answer:keyMap.get(st.num);const q=parseBlock(block,st.num,keyAnswer,source,st.prefix);q.sourceNumber=st.num;if(dups.has(st.num)){q.parseWarnings.push('Question numbering restarts or contains duplicates. Confirm that any answer key was applied correctly.');q.confidence=q.confidence==='high'?'medium':q.confidence;q.confidenceReason='Duplicate source numbering requires confirmation'}out.push(q)}if(out.length===1&&lines.filter(x=>x.trim()).length>15&&starts[0]?.kind==='fallback')throw new Error('QuestionBridge found one question in a long document but could not find question numbers. This often happens when Word automatic numbering is not exposed as text. For Word files, upload the .docx directly; for plain text, include explicit question numbers.');return out.filter(q=>q.stem.trim())}
function isSectionHeading(s=''){return /^\s*(section|unit|part|chapter|module)\b[^?]{0,80}$/i.test(String(s).trim())}
function answerMarker(line){return line.match(/^(?:Answer|Correct\s*Answer|ANS\.?|Key|Correct)\s*[:=]\s*(.+)$/i)}
function isVisualSeparatorLine(t=''){return /^[_—–-]{12,}$/.test(String(t).trim())}
