function parseCsvRows(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(q){if(c==='"'&&n==='"'){cell+='"';i++}else if(c==='"')q=false;else cell+=c}else if(c==='"')q=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows.filter(r=>r.some(c=>String(c).trim()))}
function parsePlatformCsv(text,name){const rows=parseCsvRows(text.replace(/^\uFEFF/,''));const first=(rows[0]||[]).map(x=>String(x).trim().toLowerCase());if(first[0]==='activity'&&first[1]==='type')return {questions:parsePollCsvRows(rows,name),sourceLabel:'Poll Everywhere CSV'};if(rows.some(r=>String(r[0]||'').trim().toLowerCase()==='newquestion'))return {questions:parseBrightspaceCsvRows(rows,name),sourceLabel:'Brightspace Question Library CSV'};throw new Error('This CSV does not look like a Brightspace Question Library or Poll Everywhere activity export/template.')}
function parseBrightspaceCsvRows(rows,name){const out=[];let q=null;const finish=()=>{if(!q)return;if(q.type==='tf'&&!(q.answers||[]).length)q.answers=[{text:'True',html:'',correct:false},{text:'False',html:'',correct:false}];q.confidence='high';q.confidenceReason='Imported from structured Brightspace CSV';out.push(normalizeQuestion(q));q=null};for(const r of rows){const key=String(r[0]||'').trim();if(!key||key.startsWith('//'))continue;if(key==='NewQuestion'){finish();const typeMap={MC:'mc',TF:'tf',MS:'mr',SA:'sa',WR:'essay'};q=defaultQuestion();q.type=typeMap[String(r[1]||'').trim().toUpperCase()]||'sa';q.source=`Brightspace · ${name}`;q.answers=[];q.accepted=[];continue}if(!q)continue;if(key==='Points')q.points=Number(r[1]||1);else if(key==='QuestionText'){q.stem=stripHtml(String(r[1]||''));if(String(r[2]||'').toUpperCase()==='HTML')q.stemHtml=String(r[1]||'')}else if(key==='Title')q.title=String(r[1]||'');else if(key==='Option')q.answers.push({text:stripHtml(String(r[2]||'')),html:String(r[3]||'').toUpperCase()==='HTML'?String(r[2]||''):'',correct:Number(r[1]||0)>0});else if(key==='TRUE'){q.answers.push({text:'True',html:'',correct:Number(r[1]||0)>0})}else if(key==='FALSE'){q.answers.push({text:'False',html:'',correct:Number(r[1]||0)>0})}else if(key==='Answer')q.accepted.push(String(r[2]||r[1]||''));else if(key==='Feedback')q.rationale=stripHtml(String(r[1]||''));else if(key==='Image'){const p=String(r[1]||'');q.images.push({name:p.split('/').pop()||'Brightspace image',externalPath:p,dataUrl:''})}}finish();return out.filter(q=>q.stem.trim())}
function parsePollCsvRows(rows,name){const out=[];const head=rows[0].map(x=>String(x).trim().toLowerCase()),typeI=head.indexOf('type'),titleI=head.indexOf('title'),optStart=Math.max(3,head.findIndex(x=>x.startsWith('option')));for(const r of rows.slice(1)){if(!r.some(Boolean))continue;const type=String(r[typeI]||'').toLowerCase(),title=String(r[titleI]||'').trim();if(!title)continue;const q=defaultQuestion();q.source=`Poll Everywhere · ${name}`;q.stem=title;q.answers=[];if(type.includes('multiple')){const opts=r.slice(optStart).filter(x=>String(x).trim()).map(x=>{let t=String(x),correct=t.startsWith('***');if(correct)t=t.slice(3);return {text:t,html:'',correct}});q.answers=opts;q.type=opts.filter(a=>a.correct).length>1?'mr':'mc';q.confidence=opts.some(a=>a.correct)?'high':'medium';q.confidenceReason=opts.some(a=>a.correct)?'Correct answer imported from Poll Everywhere CSV':'Poll Everywhere multiple choice imported without a marked correct answer'}else{q.type='essay';q.confidence='high';q.confidenceReason='Open-ended activity imported from Poll Everywhere'}out.push(q)}return out}
async function parseKahootXlsx(file){if(typeof XLSX==='undefined')throw new Error('The embedded spreadsheet parser could not load.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});let hi=rows.findIndex(r=>String(r[0]||'').trim().toLowerCase()==='question'&&String(r[1]||'').toLowerCase().includes('answer'));if(hi<0)hi=rows.findIndex(r=>String(r[0]||'').toLowerCase().includes('question')&&r.slice(1,5).some(x=>String(x).toLowerCase().includes('answer')));if(hi<0)throw new Error('QuestionBridge could not locate the Kahoot spreadsheet header. Use the Kahoot quiz import template/export format.');const out=[];for(const r of rows.slice(hi+1)){const stem=String(r[0]||'').trim();if(!stem)continue;const answers=r.slice(1,5).map(x=>String(x||'').trim()),correctRaw=String(r[6]??r[5]??'').trim();let correct=(correctRaw.match(/\d+/g)||[]).map(Number);if(!correct.length&&String(r[5]||'').match(/^\d+(,\s*\d+)*$/))correct=(String(r[5]).match(/\d+/g)||[]).map(Number);const q=defaultQuestion();q.source=`Kahoot · ${file.name}`;q.stem=stem;q.answers=answers.map((t,i)=>({text:t,html:'',correct:correct.includes(i+1)})).filter(a=>a.text);q.type=correct.length>1?'mr':'mc';q.confidence=correct.length?'high':'medium';q.confidenceReason=correct.length?'Correct-answer indices imported from Kahoot spreadsheet':'Kahoot spreadsheet imported without a readable correct-answer index';out.push(q)}return {questions:out,sourceLabel:'Kahoot XLSX'}}
function rtfToPlainText(rtf=''){return String(rtf).replace(/\\par[d]?\b/g,'\n').replace(/\\line\b/g,'\n').replace(/\\u(-?\d+)\??/g,(_,n)=>String.fromCharCode((Number(n)+65536)%65536)).replace(/\\'[0-9a-fA-F]{2}/g,m=>String.fromCharCode(parseInt(m.slice(2),16))).replace(/\{\\[^{}]+\s?/g,'').replace(/[{}]/g,'').replace(/\\[a-zA-Z]+-?\d*\s?/g,'').replace(/\\([\\{}])/g,'$1').replace(/\n{3,}/g,'\n\n').trim()}
function parseExamsoftRtf(text,name){const plain=rtfToPlainText(text),questions=parseTextQuestions(plain,`Legacy ExamSoft · ${name}`);questions.forEach(q=>{q.source=`Legacy ExamSoft · ${name}`;if(q.type==='fitb')q.confidence='high'});return {questions,sourceLabel:'Legacy ExamSoft RTF'}}

// Validation
const platformDefs={brightspace:{name:'Brightspace',desc:'Question Library CSV'},examsoft:{name:'Legacy ExamSoft',desc:'RTF question import'},kahoot:{name:'Kahoot',desc:'Quiz spreadsheet (.xlsx)'},poll:{name:'Poll Everywhere',desc:'Activity CSV'}};
function hasRichScripts(q){return /<(sup|sub)>/i.test(q.stemHtml||'')||(q.answers||[]).some(a=>/<(sup|sub)>/i.test(a.html||''))}
function formulaLike(s=''){return /^[=+\-@]/.test(String(s).trim())}
function baseQuestionIssues(q){const issues=[];questionStatus(q).forEach(x=>issues.push({level:'error',msg:x}));(q.parseWarnings||[]).forEach(x=>issues.push({level:'warning',msg:x}));if(q.confidence!=='high')issues.push({level:'warning',msg:`Parsing confidence: ${confidenceLabel(q)}. ${q.confidenceReason||'Confirm this question before export.'}`,kind:'confidence'});return issues}
function platformQuestionIssues(q,p){const issues=[];if(p==='brightspace'){if(q.type==='fitb')issues.push({level:'error',msg:'Brightspace Question Library CSV does not support Fill in the Blanks. Change this item to Short Answer, or export it to a destination that supports FITB.'});if(q.images?.length)issues.push({level:'warning',msg:'Image requires a Brightspace Manage Files path. Add the image folder path on the Export tab, or export without the image.'})}
if(p==='examsoft'){if(q.images?.length)issues.push({level:'warning',msg:'Legacy ExamSoft RTF import does not import images; add them after import.'});if(q.type==='sa')issues.push({level:'warning',msg:'Short Answer is exported as Fill in the Blank in legacy ExamSoft.'});if(hasRichScripts(q))issues.push({level:'warning',msg:'Superscript/subscript will be converted to Unicode or explicit scientific notation where possible; verify the preview.'})}
if(p==='kahoot'){if(!['mc','mr','tf'].includes(q.type))issues.push({level:'error',msg:'Kahoot spreadsheet import supports quiz questions only.'});const ks=q.kahootStem||q.stem;if(ks.length>95)issues.push({level:'error',msg:`Kahoot question text is ${ks.length} characters; the spreadsheet limit is 95. Add a Kahoot short version.`});const ans=cleanAnswers(q);ans.forEach((a,i)=>{if(a.text.length>60)issues.push({level:'error',msg:`Answer ${i+1} exceeds Kahoot's 60-character spreadsheet limit.`})});if(ans.length>4)issues.push({level:'error',msg:`Kahoot supports up to 4 answers in the spreadsheet importer. This question has ${ans.length}; remove or consolidate an answer before exporting.`});if(q.images?.length)issues.push({level:'warning',msg:'Images cannot be included through the spreadsheet importer.'})}
if(p==='poll'){const ps=q.pollStem||q.stem;if(ps.length>255)issues.push({level:'error',msg:`Poll Everywhere question title is ${ps.length} characters; the limit is 255. Add a Poll Everywhere short version.`});if(q.type==='essay'||q.type==='sa'||q.type==='fitb')issues.push({level:'warning',msg:q.type==='fitb'?'Fill in the Blank will be converted to an Open-ended Poll Everywhere activity; accepted answers are not carried by the CSV importer.':'Question will be converted to an Open-ended Poll Everywhere activity.'});if(q.type==='mr')issues.push({level:'warning',msg:'Multiple-response is exported as multiple choice; verify behavior after import.'});if(q.images?.length)issues.push({level:'warning',msg:'Poll Everywhere CSV import cannot upload images.'})}
if((p==='brightspace'||p==='poll')&&(formulaLike(q.stem)||cleanAnswers(q).some(a=>formulaLike(a.text))))issues.push({level:'warning',msg:'A field begins with =, +, -, or @. If you open the CSV in spreadsheet software before import, verify it remains literal text.'});return issues}
function validateQuestion(q,p){return [...baseQuestionIssues(q),...platformQuestionIssues(q,p)]}

function renderValidation(){syncEditor();const dc=$('#destinationChecks');dc.innerHTML='';Object.entries(platformDefs).forEach(([k,d])=>{const all=state.questions.flatMap(q=>[...baseQuestionIssues(q),...platformQuestionIssues(q,k)]),errs=all.filter(x=>x.level==='error').length;const lab=document.createElement('label');lab.className='qb-destination-card';lab.innerHTML=`<input type="checkbox" data-p="${k}" ${state.destinations[k]?'checked':''}><div><b>${d.name}</b><br><small class="ft-muted">${errs?errs+' blocking issue'+(errs===1?'':'s'):'Ready to export'}</small></div>`;lab.querySelector('input').onchange=e=>{state.destinations[k]=e.target.checked;saveAutosave();renderValidation()};dc.appendChild(lab)});
const selectedPlatforms=Object.keys(platformDefs).filter(p=>state.destinations[p]);const grouped=[];state.questions.forEach((q,i)=>{const general=baseQuestionIssues(q);const platforms=[];selectedPlatforms.forEach(p=>{const xs=platformQuestionIssues(q,p);if(xs.length)platforms.push({p,issues:xs})});if(general.length||platforms.length)grouped.push({q:i,general,platforms})});
const issueQs=new Set(grouped.map(g=>g.q));const blockedQs=new Set(grouped.filter(g=>g.general.some(x=>x.level==='error')||g.platforms.some(p=>p.issues.some(x=>x.level==='error'))).map(g=>g.q));const warningQs=new Set(grouped.filter(g=>g.general.some(x=>x.level==='warning')||g.platforms.some(p=>p.issues.some(x=>x.level==='warning'))).map(g=>g.q));$('#metricTotal').textContent=state.questions.length;$('#metricReady').textContent=Math.max(0,state.questions.length-issueQs.size);$('#metricAttention').textContent=issueQs.size;const md=$('#metricAttentionDetail');if(md)md.textContent=`${warningQs.size} warning${warningQs.size===1?'':'s'} · ${blockedQs.size} blocked`;const il=$('#issuesList');if(!grouped.length){il.innerHTML='<div class="ft-notice ft-notice-success"><b>✓ All selected destinations are ready.</b></div>';return}il.innerHTML=grouped.map(g=>{const hasErr=g.general.some(x=>x.level==='error')||g.platforms.some(p=>p.issues.some(x=>x.level==='error'));const general=g.general.length?`<div class="qb-issue-section"><b>General</b>${g.general.map(x=>`<div class="${x.level==='error'?'qb-platform-error':'qb-platform-warning'}">${x.level==='error'?'× BLOCKING — question cannot be exported:':'!'} ${esc(x.msg)}</div>`).join('')}</div>`:'';const plats=g.platforms.map(p=>`<div class="qb-issue-section ft-mt-2"><b>${platformDefs[p.p].name}</b>${p.issues.map(x=>`<div class="${x.level==='error'?'qb-platform-error':'qb-platform-warning'}">${x.level==='error'?'× BLOCKING — this question will not be included in the '+platformDefs[p.p].name+' export:':'!'} ${esc(x.msg)}</div>`).join('')}</div>`).join('');const needsConfirm=g.general.some(x=>x.kind==='confidence');return `<div class="qb-issue ${hasErr?'is-blocked':''}"><span class="ft-pill ${hasErr?'ft-status-error':'ft-status-warning'}">${hasErr?'×':'!'} Q${g.q+1}</span><div style="flex:1">${hasErr?'<div class="qb-blocked-banner">× Blocked from affected export</div>':''}${general}${plats}<div class="ft-btn-row ft-mt-2">${needsConfirm?`<button type="button" class="ft-btn ft-btn-primary" onclick="confirmQuestionParsing(${g.q})">Confirm parsing</button>`:''}<button type="button" class="ft-btn" onclick="openQuestion(${g.q})">Open question</button></div></div></div>`}).join('')}

window.openQuestion=i=>{state.selected=i;show('review')};
window.confirmQuestionParsing=i=>{const q=state.questions[i];if(!q)return;q.confidence='high';q.confidenceReason='Faculty confirmed the parsed question';saveAutosave();renderValidation();pop(`Question ${i+1} confirmed`)};

// Export generation
function csvCell(v){v=String(v??'');if(/^[=+\-@]/.test(v))v="'"+v;return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function unicodeScript(text,kind){const sup={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','+':'⁺','-':'⁻','=':'⁼','(':'⁽',')':'⁾','n':'ⁿ','i':'ⁱ'},sub={'0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉','+':'₊','-':'₋','=':'₌','(':'₍',')':'₎','a':'ₐ','e':'ₑ','h':'ₕ','i':'ᵢ','j':'ⱼ','k':'ₖ','l':'ₗ','m':'ₘ','n':'ₙ','o':'ₒ','p':'ₚ','r':'ᵣ','s':'ₛ','t':'ₜ','x':'ₓ'};const map=kind==='sup'?sup:sub;let ok=true,out='';for(const ch of text){if(map[ch])out+=map[ch];else{ok=false;out+=ch}}return ok?out:(kind==='sup'?`^(${text})`:`_(${text})`)}
function richToScientificText(html,fallback=''){if(!html)return fallback;const d=document.createElement('div');d.innerHTML=html;d.querySelectorAll('sup').forEach(el=>el.replaceWith(document.createTextNode(unicodeScript(el.textContent,'sup'))));d.querySelectorAll('sub').forEach(el=>el.replaceWith(document.createTextNode(unicodeScript(el.textContent,'sub'))));d.querySelectorAll('br').forEach(el=>el.replaceWith(document.createTextNode('\n')));return d.textContent||fallback}
function stripPrintedQuestionPrefix(t=''){return String(t).replace(/^\s*Question\s*#?\s*:\s*\d+\s*/i,'').replace(/^\s*(?:Q\s*)?\d+\s*[.)]\s*/i,'')}
function plainStem(q,p){if(p==='kahoot'&&q.kahootStem)return q.kahootStem;if(p==='poll'&&q.pollStem)return q.pollStem;return stripPrintedQuestionPrefix(richToScientificText(q.stemHtml,q.stem))}
function plainAnswer(a){return richToScientificText(a.html,a.text).replace(/^\s*(?:\*|[✓✔☑])?\s*[A-Z]\s*[.)]\s*/i,'')}
function selectedQuestionsFor(p){return state.questions.filter(q=>!validateQuestion(q,p).some(x=>x.level==='error'))}
function removeInferredCorrectFormatting(a){let h=String(a.html||'');if(!a.correct||!a.inferredFormat)return h;const tag=a.inferredFormat;if(!['strong','u','mark'].includes(tag))return h;const re=new RegExp('^\\s*<'+tag+'>([\\s\\S]*)<\\/'+tag+'>\\s*$','i');const m=h.match(re);return m?m[1]:h.replace(new RegExp('<\\/?'+tag+'>','gi'),'')}
function brightspaceField(text,html){const rich=html&&html!==esc(text);return [rich?html:text,rich?'HTML':'']}
function brightspaceImageFileName(q,im,idx){const qi=Math.max(1,state.questions.indexOf(q)+1);const ext=(im.name&&im.name.includes('.'))?'.'+im.name.split('.').pop().replace(/[^A-Za-z0-9]/g,'').toLowerCase():'.png';const base=(im.name||`image-${idx+1}`).replace(/\.[^.]+$/,'').replace(/[^A-Za-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'')||`image-${idx+1}`;return `Q${String(qi).padStart(2,'0')}-${base}${ext}`}
function normalizeBrightspaceFolderPath(v){return String(v||'').trim().replace(/\\/g,'/').replace(/\/{2,}/g,'/').replace(/\/+$/,'')}
function validateBrightspaceFolderPath(v){
  const raw=String(v||''); const trimmed=raw.trim(); const normalized=normalizeBrightspaceFolderPath(raw); const issues=[];
  let canFix=false;
  if(!trimmed)return {normalized:'',level:'empty',issues:[],canFix:false};
  if(/\\/.test(raw)){issues.push({level:'warning',msg:'Brightspace file paths use forward slashes (/), not backslashes (\\).'});canFix=true}
  if(raw!==trimmed||/\/{2,}/.test(trimmed.replace(/^\//,''))||/\/$/.test(trimmed))canFix=true;
  if(/^[A-Za-z]:[\\/]/.test(trimmed)||/^file:/i.test(trimmed))issues.push({level:'error',msg:'This looks like a path on your computer, not a Brightspace Manage Files path.'});
  if(/\.(png|jpe?g|gif|webp|svg)$/i.test(trimmed))issues.push({level:'warning',msg:'Paste the folder path, not the path to an individual image file.'});
  if(!normalized.startsWith('/content/'))issues.push({level:'warning',msg:'This does not look like a typical Brightspace Manage Files path. Most begin with /content/.'});
  const level=issues.some(x=>x.level==='error')?'error':issues.length?'warning':'ok';
  return {normalized,level,issues,canFix};
}
function brightspacePathFeedbackHtml(v){const r=validateBrightspaceFolderPath(v);if(r.level==='empty')return '<div class="qb-path-feedback ft-muted">Paste the folder path after you upload the image package to Brightspace.</div>';let html=r.level==='ok'?'<div class="qb-path-feedback is-ok">✓ Path looks ready. QuestionBridge will build the individual image paths automatically.</div>':`<div class="qb-path-feedback ${r.level==='error'?'is-error':'is-warn'}">${r.issues.map(x=>`${x.level==='error'?'×':'!'} ${esc(x.msg)}`).join('<br>')}</div>${r.canFix?'<div class="qb-path-actions"><button type="button" class="ft-btn fixBsPathBtn">Fix path automatically</button></div>':''}`;if(state.brightspaceCsvDownloadedPath&&r.normalized!==state.brightspaceCsvDownloadedPath)html+=`<div class="qb-path-feedback is-warn"><b>! Folder path changed after your last CSV download.</b> Download a new Brightspace CSV so it contains the current image paths.</div>`;return html}
function brightspaceImagePath(q,im,idx){const folder=normalizeBrightspaceFolderPath(state.brightspaceImageFolder);return folder?`${folder}/${brightspaceImageFileName(q,im,idx)}`:''}
function dataUrlToBlob(dataUrl){const [meta,data]=String(dataUrl||'').split(',');if(!data)return null;const mime=(meta.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const bytes=atob(data),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:mime})}
async function downloadBrightspaceImages(){try{if(typeof JSZip==='undefined')throw new Error('The ZIP generator could not load.');const z=new JSZip();let count=0;state.questions.forEach(q=>(q.images||[]).forEach((im,i)=>{const blob=dataUrlToBlob(im.dataUrl);if(blob){z.file(brightspaceImageFileName(q,im,i),blob);count++}}));if(!count)throw new Error('This question set does not contain any preserved images.');z.file('README.txt','Upload these image files together into one folder in Brightspace: Instructor Tools > Manage Files. Then copy that folder path into QuestionBridge before downloading the Brightspace CSV.\r\n');const blob=await z.generateAsync({type:'blob'});const base=safeName(state.sourceName.replace(/\.[^.]+$/,''))||'questionbridge';downloadBlob(blob,'application/zip',base+'-brightspace-images.zip');state.brightspaceImagePackageDownloaded=true;pop('Brightspace image package downloaded');renderExport()}catch(e){FTDialog.alert(e.message,{title:'Image package not created'})}}
function makeBrightspace(){const rows=[];for(const q of selectedQuestionsFor('brightspace')){const code={mc:'MC',tf:'TF',mr:'MS',sa:'SA',essay:'WR'}[q.type];rows.push(['NewQuestion',code]);if(q.points!=null)rows.push(['Points',String(q.points)]);const [qText,qFmt]=brightspaceField(stripPrintedQuestionPrefix(q.stem),stripQuestionPrefixHtml(q.stemHtml));rows.push(['QuestionText',qText,qFmt]);if(q.title)rows.push(['Title',q.title]);if(q.images?.length&&state.brightspaceImageFolder){q.images.forEach((im,i)=>rows.push(['Image',brightspaceImagePath(q,im,i)]))}const ans=cleanAnswers(q);if(q.type==='mc')ans.forEach(a=>{const safeHtml=removeInferredCorrectFormatting(a);const [txt,fmt]=brightspaceField(a.text,safeHtml);rows.push(['Option',a.correct?'100':'0',txt,fmt])});if(q.type==='mr')ans.forEach(a=>{const safeHtml=removeInferredCorrectFormatting(a);const [txt,fmt]=brightspaceField(a.text,safeHtml);rows.push(['Option',a.correct?'1':'0',txt,fmt])});if(q.type==='tf'){const t=ans.find(a=>/^true$/i.test(a.text)),f=ans.find(a=>/^false$/i.test(a.text));rows.push(['TRUE',t?.correct?'100':'0']);rows.push(['FALSE',f?.correct?'100':'0'])}if(q.type==='sa')q.accepted.filter(Boolean).forEach(a=>rows.push(['Answer','100',a]));if(q.rationale)rows.push(['Feedback',q.rationale])}return rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
function rtfUnit(code){return '\\u'+(code>32767?code-65536:code)+'?'}
function rtfEscape(s=''){let out='';for(const ch of String(s)){const cp=ch.codePointAt(0);if(ch==='\\'||ch==='{'||ch==='}')out+='\\'+ch;else if(ch==='\n')out+='\\line ';else if(cp>0xFFFF){const x=cp-0x10000,hi=0xD800+(x>>10),lo=0xDC00+(x&1023);out+=rtfUnit(hi)+rtfUnit(lo)}else if(cp>127)out+=rtfUnit(cp);else out+=ch}return out}
function examsoftFitbStem(q){
  let s=plainStem(q,'examsoft');
  const toks=detectBlankTokens(s);
  toks.forEach((t,i)=>{s=s.replace(t.token,`__ ${i+1} ___`)});
  return s;
}
function makeExamsoft(){let body='';selectedQuestionsFor('examsoft').forEach((q,i)=>{let prefix='';if(q.type==='mr')prefix='Type: MA ';if(q.type==='essay')prefix='Type: E ';if(q.type==='sa'||q.type==='fitb')prefix='Type: F ';if(q.title)prefix+=`Title: ${q.title} `;if(q.topic)prefix+=`Category: ${q.topic} `;const exportStem=q.type==='fitb'?examsoftFitbStem(q):plainStem(q,'examsoft');body+=rtfEscape(prefix+`${i+1}. ${exportStem}`)+'\\line ';if(q.rationale)body+=rtfEscape('~ '+q.rationale)+'\\line ';const ans=cleanAnswers(q);if(q.type==='sa'){const accepted=q.accepted.length?q.accepted:[''];body+=rtfEscape('a. '+accepted.join(' | '))+'\\line '}else if(q.type==='fitb'){(q.blanks||[]).forEach((b,j)=>{const vals=(b.accepted||[]).filter(Boolean);body+=rtfEscape(`${j+1}. ${vals.join('|')}${vals.length?'|':''}`)+'\\line '})}else if(q.type!=='essay'){ans.forEach((a,j)=>{body+=rtfEscape((a.correct?'*':'')+String.fromCharCode(97+j)+'. '+plainAnswer(a))+'\\line '})}body+='\\line '});return `{\\rtf1\\ansi\\uc1\\deff0{\\fonttbl{\\f0 Calibri;}}\\fs22 ${body}}`}
function makePoll(){const qs=selectedQuestionsFor('poll'),maxOpts=Math.max(6,...qs.filter(q=>!['sa','essay'].includes(q.type)).map(q=>cleanAnswers(q).length));const rows=[['Activity','Type','Title',...Array.from({length:maxOpts},(_,i)=>`Option ${i+1}`)]];qs.forEach(q=>{if(['sa','essay','fitb'].includes(q.type))rows.push(['Poll','Open-ended',plainStem(q,'poll')]);else{const opts=cleanAnswers(q).map(a=>(a.correct?'***':'')+plainAnswer(a));rows.push(['Poll','Multiple choice',plainStem(q,'poll'),...opts])}});return rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
function kahootRows(){return selectedQuestionsFor('kahoot').map(q=>{const ans=cleanAnswers(q).slice(0,4),answers=ans.map(plainAnswer);while(answers.length<4)answers.push('');const correct=ans.map((a,i)=>a.correct?i+1:null).filter(Boolean).join(',');return [plainStem(q,'kahoot'),answers[0],answers[1],answers[2],answers[3],20,correct]})}
async function makeKahootXlsxBlob(){if(typeof JSZip==='undefined')throw new Error('The XLSX generator could not load.');const aoa=[['Question - max 95 characters','Answer 1 - max 60 characters','Answer 2 - max 60 characters','Answer 3 - max 60 characters','Answer 4 - max 60 characters','Time limit (sec)','Correct answer(s) - choose at least one'],...kahootRows()];const z=new JSZip();const xmlEsc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[m]));const col=n=>{let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s};let sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';aoa.forEach((row,ri)=>{sheet+=`<row r="${ri+1}">`;row.forEach((v,ci)=>{const ref=col(ci+1)+(ri+1);if(typeof v==='number')sheet+=`<c r="${ref}"><v>${v}</v></c>`;else sheet+=`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xmlEsc(v)}</t></is></c>`});sheet+='</row>'});sheet+='</sheetData></worksheet>';z.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');z.folder('_rels').file('.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');z.folder('xl').file('workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Questions" sheetId="1" r:id="rId1"/></sheets></workbook>');z.folder('xl/_rels').file('workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');z.folder('xl').file('styles.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf xfId="0"/></cellXfs></styleSheet>');z.folder('xl/worksheets').file('sheet1.xml',sheet);return await z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function downloadBlob(content,type,name){const blob=content instanceof Blob?content:new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function renderExport(){syncEditor();const grid=$('#exportGrid');grid.innerHTML='';Object.entries(platformDefs).filter(([k])=>state.destinations[k]).forEach(([k,d])=>{const perQ=state.questions.map((q,i)=>({i,issues:validateQuestion(q,k)}));const blocked=perQ.filter(x=>x.issues.some(y=>y.level==='error')).length;const warned=perQ.filter(x=>!x.issues.some(y=>y.level==='error')&&x.issues.some(y=>y.level==='warning')).length;const good=state.questions.length-blocked;const card=document.createElement('div');card.className='ft-card qb-export-card';const status=blocked?`<span class="ft-status-error"><b>× ${blocked} QUESTION${blocked===1?'':'S'} BLOCKED</b></span>`:warned?`<span class="ft-status-warning"><b>! ${warned} QUESTION${warned===1?'':'S'} WITH WARNINGS</b></span>`:`<span class="ft-status-ready"><b>✓ ALL ${good} QUESTIONS READY</b></span>`;const summary=`<p class="ft-muted"><b>${good} of ${state.questions.length}</b> question${state.questions.length===1?'':'s'} will be included.${blocked?`<br>${blocked} question${blocked===1?'':'s'} will not be included until corrected.`:''}${warned?`<br>${warned} included question${warned===1?' has':'s have'} warnings.`:''}</p>`;let imageUi='';if(k==='brightspace'){const imageCount=state.questions.reduce((n,q)=>n+(q.images?.length||0),0);if(imageCount){const pathResult=validateBrightspaceFolderPath(state.brightspaceImageFolder);const ready=!!pathResult.normalized&&pathResult.level!=='error';imageUi=`<div class="ft-notice ft-notice-warning ft-mb-3"><b>Brightspace images · ${imageCount} preserved</b><div class="qb-image-steps"><div class="qb-image-step"><div class="qb-image-step-num">1</div><div><b>Download the image package</b><br><small class="ft-muted">QuestionBridge renames the images and keeps them matched to the correct questions.</small><div class="ft-mt-2"><button type="button" class="ft-btn imagePackageBtn">${state.brightspaceImagePackageDownloaded?'Download image package again':'Download image package'}</button></div></div></div><div class="qb-image-step"><div class="qb-image-step-num">2</div><div><b>Upload the images to Brightspace</b><br><small class="ft-muted">In your course, go to Instructor Tools → Manage Files, create or open one folder, and upload all files from the package.</small><details class="qb-help-details"><summary>Where do I find this?</summary><ol><li>Open your Brightspace course.</li><li>Choose <b>Instructor Tools → Manage Files</b>.</li><li>Create or open a folder for the QuestionBridge images.</li><li>Upload all images from the downloaded package into that folder.</li><li>Copy the folder path shown in Brightspace.</li></ol></details></div></div><div class="qb-image-step"><div class="qb-image-step-num">3</div><div><b>Paste the Brightspace Manage Files folder path</b><div class="ft-field ft-mt-2"><label>Brightspace Manage Files folder path</label><input class="ft-input bsImagePath" placeholder="/content/enforced/123456-CourseName/QuestionBridge-Images" value="${esc(state.brightspaceImageFolder||'')}"><small class="ft-muted">Example: /content/enforced/123456-CourseName/QuestionBridge-Images</small><div class="bsPathFeedback">${brightspacePathFeedbackHtml(state.brightspaceImageFolder)}</div></div></div></div><div class="qb-image-step"><div class="qb-image-step-num">4</div><div><b>Download your Brightspace CSV</b><br><small class="ft-muted">QuestionBridge will add the individual image paths automatically. Before importing, make sure all ${imageCount} image${imageCount===1?' is':'s are'} in the exact folder above.</small>${ready?`<div class="qb-image-ready">✓ ${imageCount} image path${imageCount===1?'':'s'} will be included in the CSV.</div>`:`<div class="qb-path-feedback is-warn">! Images will not be referenced until a usable folder path is entered.</div>`}</div></div></div></div>`}}card.innerHTML=`${status}<h3>${d.name}</h3>${summary}${imageUi}<div class="ft-btn-row"><button type="button" class="ft-btn previewBtn">Preview</button><button type="button" class="ft-btn ft-btn-primary downloadBtn">Download ${good}${blocked?' compatible':''}</button></div>`;const inp=card.querySelector('.bsImagePath');if(inp)inp.oninput=e=>{state.brightspaceImageFolder=e.target.value;saveAutosave();const fb=card.querySelector('.bsPathFeedback');if(fb)fb.innerHTML=brightspacePathFeedbackHtml(state.brightspaceImageFolder);const fix=card.querySelector('.fixBsPathBtn');if(fix)fix.onclick=()=>fixBrightspacePath(card)};const fix=card.querySelector('.fixBsPathBtn');if(fix)fix.onclick=()=>fixBrightspacePath(card);const ib=card.querySelector('.imagePackageBtn');if(ib)ib.onclick=downloadBrightspaceImages;card.querySelector('.previewBtn').onclick=()=>previewExport(k);card.querySelector('.downloadBtn').onclick=async e=>{e.preventDefault();e.stopPropagation();await requestExportDownload(k)};grid.appendChild(card)});if(!grid.children.length)grid.innerHTML='<div class="ft-notice ft-notice-warning">Select at least one destination on the Validate tab.</div>'}
function fixBrightspacePath(card){const inp=card?.querySelector('.bsImagePath');if(!inp)return;const fixed=normalizeBrightspaceFolderPath(inp.value);state.brightspaceImageFolder=fixed;inp.value=fixed;saveAutosave();const fb=card.querySelector('.bsPathFeedback');if(fb)fb.innerHTML=brightspacePathFeedbackHtml(fixed);const b=card.querySelector('.fixBsPathBtn');if(b)b.onclick=()=>fixBrightspacePath(card);pop('Brightspace path normalized')}
function requestExportDownload(k){if(k!=='brightspace')return downloadExport(k);const imageCount=state.questions.reduce((n,q)=>n+(q.images?.length||0),0);if(!imageCount)return downloadExport(k);const r=validateBrightspaceFolderPath(state.brightspaceImageFolder);if(!r.normalized){openBrightspaceImageConfirm(false,imageCount);return}if(r.level==='error'){FTDialog.alert('Correct the Brightspace image folder path in image setup before downloading the CSV.',{title:'Check the image folder path'});return}openBrightspaceImageConfirm(true,imageCount)}
function openBrightspaceImageConfirm(hasPath,imageCount){const folder=normalizeBrightspaceFolderPath(state.brightspaceImageFolder);$('#modalTitle').textContent=hasPath?'Confirm Brightspace image setup':'Images are not configured';$('#modalBody').innerHTML=hasPath?`<div class="ft-notice ft-notice-success"><b>${imageCount} image${imageCount===1?'':'s'} will be referenced.</b><br>QuestionBridge will use:<br><code>${esc(folder)}/</code></div><p class="ft-muted">Make sure all ${imageCount} image file${imageCount===1?' has':'s have'} been uploaded to this exact Brightspace Manage Files folder before importing the CSV.</p><div class="ft-btn-row ft-mt-4"><button type="button" class="ft-btn" id="bsBackToSetup">Back to image setup</button><button type="button" class="ft-btn ft-btn-primary" id="bsConfirmDownload">Download CSV</button></div>`:`<div class="ft-notice ft-notice-warning"><b>Your quiz contains ${imageCount} image${imageCount===1?'':'s'}.</b><br>You can download the Brightspace CSV now, but the images will not appear unless you set up the Manage Files folder path first.</div><div class="ft-btn-row ft-mt-4"><button type="button" class="ft-btn ft-btn-primary" id="bsBackToSetup">Set up images first</button><button type="button" class="ft-btn" id="bsDownloadNoImages">Download without images</button></div>`;$('#modalAction').hidden=true;modalCtl.open();const back=$('#bsBackToSetup');if(back)back.onclick=()=>{modalCtl.close();show('export')};const ok=$('#bsConfirmDownload');if(ok)ok.onclick=()=>{modalCtl.close();downloadExport('brightspace')};const no=$('#bsDownloadNoImages');if(no)no.onclick=()=>{const old=state.brightspaceImageFolder;state.brightspaceImageFolder='';modalCtl.close();downloadExport('brightspace').finally(()=>{state.brightspaceImageFolder=old})}}
function exportDescription(k,n){return {brightspace:`${n} question${n===1?'':'s'} in Brightspace Question Library CSV syntax.`,examsoft:`${n} question${n===1?'':'s'} in legacy ExamSoft RTF import syntax, including supported Fill in the Blank items.`,kahoot:`${n} compatible quiz question${n===1?'':'s'} in an .xlsx spreadsheet.`,poll:`${n} activity row${n===1?'':'s'} in Poll Everywhere CSV syntax.`}[k]}
function excludedFor(k){return state.questions.map((q,i)=>({q,i,issues:validateQuestion(q,k).filter(x=>x.level==='error')})).filter(x=>x.issues.length)}
function previewExport(k){try{let text='';if(k==='brightspace')text=makeBrightspace();if(k==='examsoft')text=stripRtfPreview(makeExamsoft());if(k==='poll')text=makePoll();if(k==='kahoot')text=[['Question','Answer 1','Answer 2','Answer 3','Answer 4','Time','Correct'],...kahootRows()].map(r=>r.join(' | ')).join('\n');const excluded=excludedFor(k);const note=excluded.length?`<div class="ft-notice ft-notice-warning ft-mb-3"><b>${excluded.length} excluded question${excluded.length===1?'':'s'}:</b> ${excluded.map(x=>`Q${x.i+1}`).join(', ')}. Resolve the blocking errors to include them.</div>`:'';openModal(`${platformDefs[k].name} preview`,`${note}<div class="qb-preview">${esc(text.slice(0,18000))}</div><p class="ft-muted ft-mt-3">${importInstructions(k)}</p>`,()=>downloadExport(k))}catch(e){console.error(e);FTDialog.alert('QuestionBridge could not generate this preview: '+(e?.message||e),{title:'Preview not available'})}}
function stripRtfPreview(r){return r.replace(/^\{\\rtf1[^ ]* /,'').replace(/\\line/g,'\n').replace(/\\u(-?\d+)\?/g,(_,n)=>String.fromCharCode((Number(n)+65536)%65536)).replace(/\\([\\{}])/g,'$1').replace(/\}$/,'')}
function importInstructions(k){return {brightspace:'Import: Brightspace → Question Library → Import → Upload a File → choose the downloaded CSV. Round-trip verification is still recommended before rollout.',examsoft:'Import: Legacy ExamSoft → Questions → Import Questions → RTF → review validation → Import Valid Questions. This profile should be verified against your current institutional portal.',kahoot:'Import: Kahoot creator → Add question → Import → Import spreadsheet → upload the downloaded .xlsx file. Verify the spreadsheet layout against the current Kahoot template before broad rollout.',poll:'Import: Poll Everywhere My Activities → Upload → select the downloaded CSV → Continue → review → Confirm. Verify correct-answer behavior in your live account before rollout.'}[k]}
async function downloadExport(k){try{const base=safeName(state.sourceName.replace(/\.[^.]+$/,''))||'questionbridge';if(k==='brightspace'){downloadBlob('\ufeff'+makeBrightspace(),'text/csv;charset=utf-8',base+'-brightspace.csv');state.brightspaceCsvDownloadedPath=normalizeBrightspaceFolderPath(state.brightspaceImageFolder)};if(k==='examsoft')downloadBlob(makeExamsoft(),'application/rtf',base+'-examsoft-legacy.rtf');if(k==='poll')downloadBlob('\ufeff'+makePoll(),'text/csv;charset=utf-8',base+'-poll-everywhere.csv');if(k==='kahoot'){const blob=await makeKahootXlsxBlob();downloadBlob(blob,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',base+'-kahoot.xlsx')}pop(`${platformDefs[k].name} export downloaded`)}catch(e){FTDialog.alert(e.message,{title:'Export not created'})}}
function safeName(s){return s.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()}
// Project persistence
function projectData(){syncEditor();return {schema:'questionbridge',version:state.version,savedAt:new Date().toISOString(),sourceName:state.sourceName,destinations:state.destinations,brightspaceImageFolder:state.brightspaceImageFolder,importSettings:state.importSettings,questions:state.questions}}
function saveProject(){downloadBlob(JSON.stringify(projectData(),null,2),'application/json',(safeName(state.sourceName)||'questionbridge')+'.questionbridge');pop('QuestionBridge project saved')}
$('#saveProject').onclick=saveProject;$('#saveProject2').onclick=saveProject;$('#openProjectBtn').onclick=()=>$('#projectInput').click();$('#projectInput').onchange=async()=>{const f=$('#projectInput').files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(d.schema!=='questionbridge'||!Array.isArray(d.questions))throw new Error('Not a valid QuestionBridge project');state.sourceName=d.sourceName||f.name;state.brightspaceImageFolder=d.brightspaceImageFolder||'';state.destinations=Object.assign(state.destinations,d.destinations||{});state.importSettings=Object.assign(state.importSettings,d.importSettings||{});state.questions=d.questions.map(normalizeQuestion);state.selected=0;saveAutosave();show('review');pop('Project opened')}catch(e){FTDialog.alert(e.message,{title:'Project could not be opened'})}};
var autosaveFailed=false;function saveAutosave(){try{localStorage.setItem('questionbridge-autosave',JSON.stringify(projectDataShallow()));autosaveFailed=!(window.FTStorage?.persistent??true);$('#autosaveBanner').style.display=autosaveFailed?'block':'none'}catch(e){autosaveFailed=true;console.warn('Autosave unavailable',e);$('#autosaveBanner').style.display='block'}}function projectDataShallow(){return {schema:'questionbridge',version:state.version,sourceName:state.sourceName,destinations:state.destinations,brightspaceImageFolder:state.brightspaceImageFolder,importSettings:state.importSettings,questions:state.questions.map(q=>({...q,images:(q.images||[]).map(im=>im.dataUrl?.length>250000?{name:im.name,dataUrl:''}:im)}))}}
function restoreAutosave(){try{const d=JSON.parse(localStorage.getItem('questionbridge-autosave')||'null');if(d?.schema==='questionbridge'&&d.questions?.length){state.sourceName=d.sourceName||state.sourceName;state.brightspaceImageFolder=d.brightspaceImageFolder||'';state.destinations=Object.assign(state.destinations,d.destinations||{});state.importSettings=Object.assign(state.importSettings,d.importSettings||{});state.questions=d.questions.map(normalizeQuestion);state.selected=0;$('#restoredText').textContent=`Restored ${state.questions.length} question${state.questions.length===1?'':'s'} from your last session.`;$('#restoredBanner').style.display='block'}}catch(e){}}
$('#dismissRestore').onclick=()=>$('#restoredBanner').style.display='none';$('#freshAfterRestore').onclick=()=>{localStorage.removeItem('questionbridge-autosave');state.questions=[];state.selected=0;state.brightspaceImageFolder='';$('#restoredBanner').style.display='none';renderReview();show('upload');pop('Started fresh')};
// Theme + modal
function applyTheme(theme){if(theme==='dark')document.documentElement.dataset.ftTheme='dark';else delete document.documentElement.dataset.ftTheme;localStorage.setItem('ft-theme',theme)}if(localStorage.getItem('ft-theme')==='dark')applyTheme('dark');$('#themeBtn').onclick=()=>applyTheme(document.documentElement.dataset.ftTheme==='dark'?'light':'dark');
// Shared pop-up: Escape, ×, Close, and outside clicks all close it; modalDismiss runs only when it is cancelled.
let modalDismiss=null;const modalCtl=FTDialog.manage($('#modal'),{onClose:()=>{const f=modalDismiss;modalDismiss=null;f?.()}});function openModal(title,html,action){modalDismiss=null;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalAction').hidden=!action;$('#modalAction').onclick=()=>{modalDismiss=null;modalCtl.close();action?.()};modalCtl.open()}
FTUnsavedWork.watch(()=>autosaveFailed&&state.questions.length>0);
restoreAutosave();$('#correctMarking').value=state.importSettings.correctMarking||'auto';renderReview();
